// probeFolderChildren returns the folder's children in wire order and the
// folder payload itself from a user-data response.
func probeFolderChildren(data *pb.PBUserDataResponse, folderID string) ([]*pb.PBListFolderItem, *pb.PBListFolder, bool) {
	for _, folder := range data.GetListFoldersResponse().GetListFolders() {
		if folder.GetIdentifier() == folderID {
			return folder.GetItems(), folder, true
		}
	}
	return nil, nil, false
}

// probeFindParentFolderID returns the identifier of the folder whose items
// contain childID, or "" when no folder lists it.
func probeFindParentFolderID(data *pb.PBUserDataResponse, childID string) string {
	for _, folder := range data.GetListFoldersResponse().GetListFolders() {
		for _, item := range folder.GetItems() {
			if item.GetIdentifier() == childID {
				return folder.GetIdentifier()
			}
		}
	}
	return ""
}

// probeAllShoppingLists flattens the new and modified list buckets that a
// stateless user-data read populates.
func probeAllShoppingLists(data *pb.PBUserDataResponse) []*pb.ShoppingList {
	slr := data.GetShoppingListsResponse()
	if slr == nil {
		return nil
	}
	return append(append([]*pb.ShoppingList{}, slr.GetNewLists()...), slr.GetModifiedLists()...)
}

func probeListByID(data *pb.PBUserDataResponse, listID string) (*pb.ShoppingList, bool) {
	for _, list := range probeAllShoppingLists(data) {
		if list.GetIdentifier() == listID {
			return list, true
		}
	}
	return nil, false
}

func probeFolderNameTaken(data *pb.PBUserDataResponse, name string) bool {
	for _, folder := range data.GetListFoldersResponse().GetListFolders() {
		if strings.EqualFold(strings.TrimSpace(folder.GetName()), name) {
			return true
		}
	}
	return false
}

func probeListNameTaken(data *pb.PBUserDataResponse, name string) bool {
	for _, list := range probeAllShoppingLists(data) {
		if strings.EqualFold(strings.TrimSpace(list.GetName()), name) {
			return true
		}
	}
	return false
}

func probeItemsKey(items []*pb.PBListFolderItem) string {
	parts := make([]string, 0, len(items))
	for _, item := range items {
		parts = append(parts, fmt.Sprintf("%s:%d", item.GetIdentifier(), item.GetItemType()))
	}
	return strings.Join(parts, "|")
}

func probeReversed(items []*pb.PBListFolderItem) []*pb.PBListFolderItem {
	out := make([]*pb.PBListFolderItem, 0, len(items))
	for i := len(items) - 1; i >= 0; i-- {
		out = append(out, items[i])
	}
	return out
}

