// TestFolderOrderingCleanupRetry is a post-probe remediation mode, run ONLY
// when ANYLIST_FOLDER_ORDERING_PROBE=cleanup. It identifies (never creates)
// the disposable "Inbox" fixture folder left behind by a prior probe run
// whose folder deletion was acknowledged without persistence, and attempts
// the remaining bounded, evidence-based delete-folder-items variants. If the
// folder is already absent it does nothing. Production folders are never
// touched: the target must be the exact fixture name.
func TestFolderOrderingCleanupRetry(t *testing.T) {
	if os.Getenv(folderOrderingProbeEnvVar) != "cleanup" {
		t.Skip("set ANYLIST_FOLDER_ORDERING_PROBE=cleanup to retry deletion of a leftover probe fixture folder")
	}
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Minute)
	defer cancel()

	cfg, err := config.Load("")
	if err != nil {
		t.Fatalf("loading AnyList config: %v", err)
	}
	if cfg.AccessToken == "" && cfg.AuthHeaderVal == "" {
		t.Fatalf("no AnyList credentials found in %s; run 'anylist-pp-cli auth login' first", cfg.Path)
	}
	c := New(cfg)
	say := func(format string, a ...any) { t.Logf("[folder-ordering-cleanup] "+format, a...) }

	fresh, err := c.GetUserData(ctx)
	if err != nil {
		t.Fatalf("fresh read failed: %v", err)
	}
	var target *pb.PBListFolder
	for _, folder := range fresh.GetListFoldersResponse().GetListFolders() {
		if strings.EqualFold(strings.TrimSpace(folder.GetName()), probeFixtureFolderName) {
			target = folder
		}
	}
	if target == nil {
		say("fixture folder %q is already absent; nothing to do", probeFixtureFolderName)
		return
	}
	listDataID := fresh.GetListFoldersResponse().GetListDataId()
	if len(target.GetItems()) > 0 {
		// The fixture lists were removed by the probe; if the folder still
		// references children, remove each with the live-verified
		// delete-folder-items shape before attempting the folder deletion.
		for _, child := range target.GetItems() {
			childOp := &pb.PBListFolderOperation{
				Metadata:    &pb.PBOperationMetadata{OperationId: uuid.NewString(), HandlerId: "delete-folder-items", UserId: cfg.UserID},
				ListDataId:  listDataID,
				FolderItems: []*pb.PBListFolderItem{proto.Clone(child).(*pb.PBListFolderItem)},
			}
			if err := probeSendFolderOperation(ctx, c, "operations", childOp); err != nil {
				say("child %q removal send error: %v", child.GetIdentifier(), err)
				continue
			}
			childFresh, err := c.GetUserData(ctx)
			if err == nil {
				if children, _, ok := probeFolderChildren(childFresh, target.GetIdentifier()); ok {
					for _, remaining := range children {
						if remaining.GetIdentifier() == child.GetIdentifier() {
							say("child %q removal acknowledged but child still listed under the fixture folder", child.GetIdentifier())
						}
					}
				}
			}
		}
		fresh, err = c.GetUserData(ctx)
		if err != nil {
			t.Fatalf("fresh read after child cleanup: %v", err)
		}
		for _, folder := range fresh.GetListFoldersResponse().GetListFolders() {
			if folder.GetIdentifier() == target.GetIdentifier() && len(folder.GetItems()) > 0 {
				t.Fatalf("fixture folder %q still has %d children after cleanup; stopping", probeFixtureFolderName, len(folder.GetItems()))
			}
		}
	}
	parent := probeFindParentFolderID(fresh, target.GetIdentifier())
	if parent == "" {
		parent = fresh.GetListFoldersResponse().GetRootFolderId()
	}

	variants := []struct {
		name string
		op   func() *pb.PBListFolderOperation
	}{
		{
			name: "delete-folder-items-with-original-parent",
			op: func() *pb.PBListFolderOperation {
				return &pb.PBListFolderOperation{
					Metadata:               &pb.PBOperationMetadata{OperationId: uuid.NewString(), HandlerId: "delete-folder-items", UserId: cfg.UserID},
					ListDataId:             listDataID,
					FolderItems:            []*pb.PBListFolderItem{{Identifier: target.GetIdentifier(), ItemType: int32(pb.PBListFolderItem_FolderType)}},
					OriginalParentFolderId: parent,
				}
			},
		},
		{
			name: "delete-folder-items-with-folder-payload",
			op: func() *pb.PBListFolderOperation {
				return &pb.PBListFolderOperation{
					Metadata:               &pb.PBOperationMetadata{OperationId: uuid.NewString(), HandlerId: "delete-folder-items", UserId: cfg.UserID},
					ListDataId:             listDataID,
					ListFolder:             proto.Clone(target).(*pb.PBListFolder),
					FolderItems:            []*pb.PBListFolderItem{{Identifier: target.GetIdentifier(), ItemType: int32(pb.PBListFolderItem_FolderType)}},
					OriginalParentFolderId: parent,
				}
			},
		},
	}

	for _, variant := range variants {
		if err := probeSendFolderOperation(ctx, c, "operations", variant.op()); err != nil {
			say("variant %s: send error: %v", variant.name, err)
			continue
		}
		fresh2, err := c.GetUserData(ctx)
		if err != nil {
			say("variant %s: fresh read-back failed: %v", variant.name, err)
			continue
		}
		_, _, stillThere := probeFolderChildren(fresh2, target.GetIdentifier())
		if stillThere {
			say("variant %s: HTTP 200, folder %q still present in fresh read", variant.name, probeFixtureFolderName)
			continue
		}
		say("variant %s: PERSISTED — fixture folder %q removed and verified absent", variant.name, probeFixtureFolderName)
		t.Log("CLEANUP-RETRY-SUMMARY winner=" + variant.name)
		return
	}
	say("all deletion variants acknowledged without persistence; the fixture folder %q requires manual deletion in the AnyList app", probeFixtureFolderName)
	t.Log("CLEANUP-RETRY-SUMMARY winner=none")
}

func TestProbeOrderHelpers(t *testing.T) {
	t.Parallel()

	items := []*pb.PBListFolderItem{
		{Identifier: "a", ItemType: int32(pb.PBListFolderItem_ListType)},
		{Identifier: "b", ItemType: int32(pb.PBListFolderItem_FolderType)},
		{Identifier: "c", ItemType: int32(pb.PBListFolderItem_ListType)},
	}
	reversed := probeReversed(items)
	if probeItemsKey(reversed) != "c:0|b:1|a:0" {
		t.Fatalf("reversed key = %q, want c:0|b:1|a:0", probeItemsKey(reversed))
	}
	if len(items) != 3 {
		t.Fatal("reversal mutated the input slice length")
	}

	data := &pb.PBUserDataResponse{
		ShoppingListsResponse: &pb.ShoppingListsResponse{
			NewLists:      []*pb.ShoppingList{{Identifier: "l1", Name: "Pantry"}},
			ModifiedLists: []*pb.ShoppingList{{Identifier: "l2", Name: "Closet"}},
		},
		ListFoldersResponse: &pb.PBListFoldersResponse{
			RootFolderId: "root",
			ListFolders: []*pb.PBListFolder{
				{Identifier: "root", Name: "Lists", Items: []*pb.PBListFolderItem{
					{Identifier: "l1", ItemType: int32(pb.PBListFolderItem_ListType)},
					{Identifier: "f1", ItemType: int32(pb.PBListFolderItem_FolderType)},
				}},
				{Identifier: "f1", Name: "Inbox"},
			},
		},
	}
	if parent := probeFindParentFolderID(data, "f1"); parent != "root" {
		t.Fatalf("parent of f1 = %q, want root", parent)
	}
	if parent := probeFindParentFolderID(data, "missing"); parent != "" {
		t.Fatalf("parent of missing child = %q, want empty", parent)
	}
	if _, ok := probeListByID(data, "l2"); !ok {
		t.Fatal("list l2 must be found in the modified bucket")
	}
	if _, ok := probeListByID(data, "nope"); ok {
		t.Fatal("missing list must not resolve")
	}
	if !probeFolderNameTaken(data, "inbox") {
		t.Fatal("folder name match must be case-insensitive")
	}
	if !probeListNameTaken(data, "PANTRY") {
		t.Fatal("list name match must be case-insensitive")
	}
}

func TestFolderOrderingLiveProbe(t *testing.T) {
	if os.Getenv(folderOrderingProbeEnvVar) != "1" {
		t.Skipf("set %s=1 to run the live folder-ordering probe against the configured AnyList account (no live requests are made otherwise)", folderOrderingProbeEnvVar)
	}
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Minute)
	defer cancel()

	cfg, err := config.Load("")
	if err != nil {
		t.Fatalf("loading AnyList config: %v", err)
	}
	if cfg.AccessToken == "" && cfg.AuthHeaderVal == "" {
		t.Fatalf("no AnyList credentials found in %s; run 'anylist-pp-cli auth login' first", cfg.Path)
	}
	c := New(cfg)
	say := func(format string, a ...any) { t.Logf("[folder-ordering-probe] "+format, a...) }

	res := &folderOrderingProbeOutcome{winner: "none", createFolder: "not-attempted"}
	res.details = append(res.details, "gated by "+folderOrderingProbeEnvVar)

	cleanupRan := false
	fxFolderID := ""
	var fxLists []probeFixtureList

	runCleanup := func() {
		if cleanupRan {
			return
		}
		cleanupRan = true
		parts := []string{}
		failed := false

		for i := len(fxLists) - 1; i >= 0; i-- {
			fl := fxLists[i]
			err := c.RemoveList(ctx, fl.id)
			fresh, readErr := c.GetUserData(ctx)
			_, stillThere := probeListByID(fresh, fl.id)
			if err != nil || readErr != nil || stillThere {
				say("CLEANUP FAIL list %q: remove err=%v read err=%v still_present=%v", fl.name, err, readErr, stillThere)
				failed = true
				parts = append(parts, fl.name+"=PRESENT")
				continue
			}
			say("CLEANUP OK list %q removed and verified absent", fl.name)
			parts = append(parts, fl.name+"=gone")
		}

		if fxFolderID != "" {
			fresh, readErr := c.GetUserData(ctx)
			if readErr != nil {
				say("CLEANUP FAIL folder %q: cannot fresh-read before folder removal: %v", probeFixtureFolderName, readErr)
				failed = true
				parts = append(parts, probeFixtureFolderName+"=UNKNOWN")
			} else {
				// Live-verified 2026-08-23: deleting a FolderType child
				// requires originalParentFolderId; the folderItems-only shape
				// (verified for list-item deletion) is acknowledged without
				// persisting for folders.
				parent := probeFindParentFolderID(fresh, fxFolderID)
				if parent == "" {
					parent = fresh.GetListFoldersResponse().GetRootFolderId()
				}
				op := &pb.PBListFolderOperation{
					Metadata:               &pb.PBOperationMetadata{OperationId: uuid.NewString(), HandlerId: "delete-folder-items", UserId: cfg.UserID},
					ListDataId:             fresh.GetListFoldersResponse().GetListDataId(),
					FolderItems:            []*pb.PBListFolderItem{{Identifier: fxFolderID, ItemType: int32(pb.PBListFolderItem_FolderType)}},
					OriginalParentFolderId: parent,
				}
				sendErr := probeSendFolderOperation(ctx, c, "operations", op)
				fresh2, readErr2 := c.GetUserData(ctx)
				_, _, stillThere := probeFolderChildren(fresh2, fxFolderID)
				if sendErr != nil || readErr2 != nil || stillThere {
					say("CLEANUP FAIL folder %q: delete err=%v read err=%v still_present=%v — manual deletion required in the AnyList app", probeFixtureFolderName, sendErr, readErr2, stillThere)
					failed = true
					parts = append(parts, probeFixtureFolderName+"=PRESENT")
				} else {
					say("CLEANUP OK folder %q removed and verified absent", probeFixtureFolderName)
					parts = append(parts, probeFixtureFolderName+"=gone")
				}
			}
		}
		res.cleanup = strings.Join(parts, " ")
		if failed {
			t.Errorf("probe cleanup left fixtures behind: %s", res.cleanup)
		}
	}
	defer runCleanup()

	say("stage 0: baseline fresh read")
	data, err := c.GetUserData(ctx)
	if err != nil {
		t.Fatalf("baseline fresh read failed: %v", err)
	}
	rootID := data.GetListFoldersResponse().GetRootFolderId()
	listDataID := data.GetListFoldersResponse().GetListDataId()
	if rootID == "" || listDataID == "" {
		t.Fatalf("live user-data response is missing rootFolderId or listDataId")
	}
	for _, name := range []string{probeFixtureFolderName, probeFixtureListOne, probeFixtureListTwo} {
		if probeFolderNameTaken(data, name) || probeListNameTaken(data, name) {
			res.details = append(res.details, "aborted: live name collision for "+name)
			t.Log("SUMMARY " + res.summary())
			t.Skipf("fixture name %q already exists live; refusing to guess (no live writes attempted)", name)
		}
	}

	// Stage 1: fixture folder.
	say("stage 1: create fixture folder %q via create-new-folder", probeFixtureFolderName)
	fxFolderID = strings.ReplaceAll(uuid.NewString(), "-", "")
	createOp := &pb.PBListFolderOperation{
		Metadata: &pb.PBOperationMetadata{
			OperationId: uuid.NewString(),
			HandlerId:   "create-new-folder",
			UserId:      cfg.UserID,
		},
		ListDataId: listDataID,
		ListFolder: &pb.PBListFolder{
			Identifier:     fxFolderID,
			Name:           probeFixtureFolderName,
			Timestamp:      float64(time.Now().Unix()),
			FolderSettings: &pb.PBListFolderSettings{},
		},
		UpdatedParentFolderId: rootID,
	}
	createErr := probeSendFolderOperation(ctx, c, "operations", createOp)
	fresh, err := c.GetUserData(ctx)
	if err != nil {
		t.Fatalf("fresh read after folder create: %v", err)
	}
	_, _, folderLive := probeFolderChildren(fresh, fxFolderID)
	if createErr != nil {
		say("create-new-folder send error: %v", createErr)
	}
	if !folderLive {
		res.createFolder = "absent"
		res.details = append(res.details, fmt.Sprintf("create-new-folder send_err=%v", createErr))
		res.cleanup = "n/a (no fixture created)"
		t.Log("SUMMARY " + res.summary())
		runCleanup()
		say("conclusion: create-new-folder was not persisted (HTTP 200 without persistence or send error). The app dex pool contains no folder-delete handler, so a persisting create could not be cleaned up; no disposable folder exists to identify. set-ordered-folder-items remains untestable without a fixture and the production gate stays fail-closed")
		return
	}
	res.createFolder = "persisted"
	say("fixture folder %q persisted (fresh read confirms it)", probeFixtureFolderName)

	// Stage 2: fixture lists, moved into the fixture folder.
	say("stage 2: create fixture lists %q and %q, then move them into the fixture folder", probeFixtureListOne, probeFixtureListTwo)
	moved := 0
	for _, name := range []string{probeFixtureListOne, probeFixtureListTwo} {
		list, err := c.CreateList(ctx, name)
		if err != nil {
			say("fixture list %q create error: %v", name, err)
			res.details = append(res.details, fmt.Sprintf("list %q create_err", name))
			break
		}
		fxLists = append(fxLists, probeFixtureList{name: name, id: list.GetIdentifier()})
		fresh, err = c.GetUserData(ctx)
		if err != nil {
			t.Fatalf("fresh read after creating list %q: %v", name, err)
		}
		created, ok := probeListByID(fresh, list.GetIdentifier())
		if !ok {
			say("fixture list %q acknowledged but NOT present in fresh read; stopping fixture build", name)
			res.details = append(res.details, fmt.Sprintf("list %q not-persisted", name))
			break
		}
		say("fixture list %q created and present in fresh read", name)

		parent := probeFindParentFolderID(fresh, created.GetIdentifier())
		if parent == "" {
			parent = rootID
		}
		moveOp := &pb.PBListFolderOperation{
			Metadata: &pb.PBOperationMetadata{
				OperationId: uuid.NewString(),
				HandlerId:   "move-folder-items",
				UserId:      cfg.UserID,
			},
			ListDataId:             listDataID,
			FolderItems:            []*pb.PBListFolderItem{{Identifier: created.GetIdentifier(), ItemType: int32(pb.PBListFolderItem_ListType)}},
			OriginalParentFolderId: parent,
			UpdatedParentFolderId:  fxFolderID,
		}
		if err := probeSendFolderOperation(ctx, c, "operations", moveOp); err != nil {
			say("move-folder-items for %q send error: %v", name, err)
			res.details = append(res.details, fmt.Sprintf("list %q move_err", name))
			continue
		}
		fresh, err = c.GetUserData(ctx)
		if err != nil {
			t.Fatalf("fresh read after moving list %q: %v", name, err)
		}
		children, _, _ := probeFolderChildren(fresh, fxFolderID)
		inside := false
		for _, item := range children {
			if item.GetIdentifier() == created.GetIdentifier() {
				inside = true
			}
		}
		if !inside {
			say("move-folder-items for %q acknowledged but the list is NOT under the fixture folder in the fresh read", name)
			res.details = append(res.details, fmt.Sprintf("list %q move-not-persisted", name))
			continue
		}
		moved++
		say("fixture list %q moved into the fixture folder and confirmed by fresh read", name)
	}
	res.fixtureLists = fmt.Sprintf("%d/2", len(fxLists))
	res.fixtureMoves = fmt.Sprintf("%d/2", moved)

	children, _, ok := probeFolderChildren(fresh, fxFolderID)
	if !ok || len(children) < 2 {
		res.details = append(res.details, fmt.Sprintf("fixture folder children=%d (<2)", len(children)))
		t.Log("SUMMARY " + res.summary())
		runCleanup()
		say("conclusion: fixture children could not be placed under the fixture folder; set-ordered-folder-items remains unverified and the production gate stays fail-closed")
		return
	}

	// Stage 3: bounded candidate variants, fresh read-back after each.
	say("stage 3: five bounded set-ordered-folder-items candidates (target = reversed child order)")
	order0Items := children
	order0Key := probeItemsKey(order0Items)
	targetItems := probeReversed(order0Items)
	targetKey := probeItemsKey(targetItems)

	now := float64(time.Now().Unix())
	liveFolder := func() (*pb.PBListFolder, error) {
		data, err := c.GetUserData(ctx)
		if err != nil {
			return nil, err
		}
		_, folder, found := probeFolderChildren(data, fxFolderID)
		if !found {
			return nil, fmt.Errorf("fixture folder missing from fresh read")
		}
		return folder, nil
	}
	candidates := []struct {
		name string
		send func(items []*pb.PBListFolderItem) error
	}{
		{
			name: "A-listFolder-complete-payload",
			send: func(items []*pb.PBListFolderItem) error {
				folder, err := liveFolder()
				if err != nil {
					return err
				}
				// The exact typed production operation.
				return c.SetOrderedFolderItems(ctx, listDataID, folder, items)
			},
		},
		{
			name: "B-listFolder-refreshed-timestamp",
			send: func(items []*pb.PBListFolderItem) error {
				folder, err := liveFolder()
				if err != nil {
					return err
				}
				op := &pb.PBListFolderOperation{
					Metadata:   &pb.PBOperationMetadata{OperationId: uuid.NewString(), HandlerId: "set-ordered-folder-items", UserId: cfg.UserID},
					ListDataId: listDataID,
					ListFolder: cloneFolderWithItems(folder, items),
				}
				op.ListFolder.Timestamp = now
				return probeSendFolderOperation(ctx, c, "operations", op)
			},
		},
		{
			name: "C-listFolder-part-name-list-folder-operations",
			send: func(items []*pb.PBListFolderItem) error {
				folder, err := liveFolder()
				if err != nil {
					return err
				}
				op := &pb.PBListFolderOperation{
					Metadata:   &pb.PBOperationMetadata{OperationId: uuid.NewString(), HandlerId: "set-ordered-folder-items", UserId: cfg.UserID},
					ListDataId: listDataID,
					ListFolder: cloneFolderWithItems(folder, items),
				}
				return probeSendFolderOperation(ctx, c, "list-folder-operations", op)
			},
		},
		{
			name: "D-listFolder-plus-folderItems-plus-parent",
			send: func(items []*pb.PBListFolderItem) error {
				folder, err := liveFolder()
				if err != nil {
					return err
				}
				op := &pb.PBListFolderOperation{
					Metadata:              &pb.PBOperationMetadata{OperationId: uuid.NewString(), HandlerId: "set-ordered-folder-items", UserId: cfg.UserID},
					ListDataId:            listDataID,
					ListFolder:            cloneFolderWithItems(folder, items),
					FolderItems:           items,
					UpdatedParentFolderId: rootID,
				}
				return probeSendFolderOperation(ctx, c, "operations", op)
			},
		},
		{
			name: "E-folderItems-with-parents",
			send: func(items []*pb.PBListFolderItem) error {
				op := &pb.PBListFolderOperation{
					Metadata:               &pb.PBOperationMetadata{OperationId: uuid.NewString(), HandlerId: "set-ordered-folder-items", UserId: cfg.UserID},
					ListDataId:             listDataID,
					FolderItems:            items,
					OriginalParentFolderId: rootID,
					UpdatedParentFolderId:  rootID,
				}
				return probeSendFolderOperation(ctx, c, "operations", op)
			},
		},
	}

	for _, candidate := range candidates {
		res.candidates++
		// Re-baseline before every candidate: the state must be exactly the
		// original order, otherwise the fixture is in an uncontrolled state
		// and further candidates are meaningless.
		data, err := c.GetUserData(ctx)
		if err != nil {
			res.details = append(res.details, fmt.Sprintf("%s pre-read err", candidate.name))
			break
		}
		cur, _, found := probeFolderChildren(data, fxFolderID)
		if !found {
			res.details = append(res.details, fmt.Sprintf("%s fixture-folder-missing", candidate.name))
			break
		}
		if probeItemsKey(cur) != order0Key {
			res.details = append(res.details, fmt.Sprintf("%s skipped (state uncontrolled: observed %d children != baseline)", candidate.name, len(cur)))
			say("fixture state deviated from baseline before %s; stopping candidates", candidate.name)
			break
		}
		if err := candidate.send(targetItems); err != nil {
			say("candidate %s: server/transport error: %v", candidate.name, err)
			res.details = append(res.details, fmt.Sprintf("%s send-err", candidate.name))
			continue
		}
		fresh, err := c.GetUserData(ctx)
		if err != nil {
			say("candidate %s: fresh read-back failed: %v", candidate.name, err)
			res.details = append(res.details, fmt.Sprintf("%s read-err", candidate.name))
			continue
		}
		children, _, found = probeFolderChildren(fresh, fxFolderID)
		if !found {
			say("candidate %s: fixture folder absent from fresh read-back", candidate.name)
			res.details = append(res.details, fmt.Sprintf("%s folder-missing-after", candidate.name))
			continue
		}
		observed := probeItemsKey(children)
		switch {
		case observed == targetKey:
			res.winner = candidate.name
			res.details = append(res.details, fmt.Sprintf("%s PERSISTED", candidate.name))
			say("candidate %s: PERSISTED — fresh read-back shows the exact requested order", candidate.name)
		case observed == order0Key:
			res.details = append(res.details, fmt.Sprintf("%s http-200-no-change", candidate.name))
			say("candidate %s: HTTP 200, fresh read-back shows the original order (no change)", candidate.name)
		default:
			res.details = append(res.details, fmt.Sprintf("%s uncontrolled-change(%d children)", candidate.name, len(children)))
			say("candidate %s: fresh read-back shows an order that is NEITHER the requested one NOR the original; attempting to restore the original order with the same candidate shape", candidate.name)
			restored := false
			if err := candidate.send(order0Items); err == nil {
				fresh2, err2 := c.GetUserData(ctx)
				if err2 == nil {
					children2, _, ok2 := probeFolderChildren(fresh2, fxFolderID)
					restored = ok2 && probeItemsKey(children2) == order0Key
				}
			}
			if restored {
				res.details = append(res.details, fmt.Sprintf("%s restored", candidate.name))
				say("candidate %s: original order restored and verified by fresh read", candidate.name)
			} else {
				say("candidate %s: original order could NOT be restored; fixture order is uncontrolled; stopping candidates", candidate.name)
				break
			}
		}
		if res.winner != "none" {
			break
		}
	}

	t.Log("SUMMARY " + res.summary())
	runCleanup()
	if res.winner != "none" {
		say("conclusion: %s is the live-verified set-ordered-folder-items payload; the production --apply child-ordering path may be enabled with fresh read-back verification", res.winner)
	} else {
		say("conclusion: no candidate produced a persisted child order; set-ordered-folder-items remains unverified and the production gate stays fail-closed")
	}
}
